import{_ as a,o as s,c as e,a5 as n}from"./chunks/framework.CslsFoWx.js";const h=JSON.parse('{"title":"Stock & inventaire","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/05-inventory.md","filePath":"generated/modules/05-inventory.md","lastUpdated":null}'),d={name:"modules/05-inventory.md"};function r(o,t,i,p,l,u){return s(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="stock-inventaire" tabindex="-1">Stock &amp; inventaire <a class="header-anchor" href="#stock-inventaire" aria-label="Permalink to &quot;Stock &amp; inventaire&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 1–3 · <a href="/VendoraSystem-docs/specs/05-inventory">spécification complète</a></span></p><p>Le stock est un journal de mouvements signés et append-only, jamais une quantité éditable. Sont livrés : les sorties à la vente (y compris additions et offerts), les retours et annulations contre-passés, la projection serveur, le badge de stock en caisse et l&#39;écran Stock au back-office avec seuil bas et CMP. S&#39;y ajoutent les inventaires (comptage hors ligne sur les caisses, conflits entre compteurs, validation en delta sous PIN) et les pertes et vols sous PIN manager. Restent le mouvement inverse, le stock négatif configurable, les lots et DLC, les variantes, les fiches techniques, les transferts et les agrégats anti-fraude.</p><div class="kpis"><div><b>22</b><span>faites</span></div><div><b>1</b><span>partielles</span></div><div><b>2</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="journal-des-mouvements" tabindex="-1">Journal des mouvements <a class="header-anchor" href="#journal-des-mouvements" aria-label="Permalink to &quot;Journal des mouvements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Mouvements signés et append-only</strong><br><span class="muted">Chaque variation de stock est un mouvement typé, signé (utilisateur, appareil, session, date), jamais modifié ni supprimé.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-STOCK-01, RG-STOCK-02, RG-STOCK-03, RG-STOCK-04</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-stock-web">📷</a></td></tr><tr><td><strong>Projection serveur du stock</strong><br><span class="muted">Le serveur projette les mouvements reçus (idempotence par identifiant, anomalies journalisées, rattrapage au démarrage) et calcule le stock comme leur somme.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-STOCK-01, RG-STOCK-02</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-stock-web">📷</a></td></tr></tbody></table><h2 id="mouvements-generes-par-la-vente" tabindex="-1">Mouvements générés par la vente <a class="header-anchor" href="#mouvements-generes-par-la-vente" aria-label="Permalink to &quot;Mouvements générés par la vente&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Sortie de stock à la vente</strong><br><span class="muted">La vente émet ses mouvements SALE dans la même transaction, hors ligne compris, pour les seuls produits suivis en stock.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-STOCK-07, RG-STOCK-20</td><td>1.x, 2.7, 2.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-ios">📷</a></td></tr><tr><td><strong>Retours et annulations contre-passés</strong><br><span class="muted">Un retour ou une annulation remet le produit en stock (RETURN), avec une perte LOSS si le produit est déclaré cassé.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-STOCK-07</td><td>2.20, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-annulations-retours">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Offerts et additions</strong><br><span class="muted">Une ligne offerte sort quand même du stock, et la sortie d&#39;une addition partagée est faite une seule fois par la première part.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-STOCK-07</td><td>2.7, 2.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-addition">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-operations-addition">📷</a></td></tr><tr><td><strong>Mode formation sans effet sur le stock</strong><br><span class="muted">Les ventes du mode formation ne génèrent aucun mouvement de stock.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td></td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-formation-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-formation-ios">📷</a></td></tr><tr><td><strong>Quantités au poids en millièmes</strong><br><span class="muted">Les quantités sont transportées en millièmes entiers, ce qui permet de suivre le stock de produits vendus au kilo ou au litre.<br><i>Moteur et mouvements en millièmes ; la vente au poids en caisse (balance, spec 11) n&#39;est pas prouvée à l&#39;écran.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td>RG-STOCK-17</td><td>0.x, 1.x</td><td></td></tr></tbody></table><h2 id="consultation" tabindex="-1">Consultation <a class="header-anchor" href="#consultation" aria-label="Permalink to &quot;Consultation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Stock local affiché en caisse</strong><br><span class="muted">La caisse affiche un badge de stock alimenté par ses ventes et par celles des autres caisses reçues au pull.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-STOCK-01</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-ios">📷</a></td></tr><tr><td><strong>Écran Stock du back-office</strong><br><span class="muted">Le gérant voit le stock projeté par produit et le journal de ses mouvements, sans aucun champ quantité éditable.<br><i>Lot R4 : page « Journal du stock » — filtres type, catégorie, utilisateur, appareil, période (fin incluse), export CSV des mêmes filtres (séparateur « ; », BOM Excel, fuseau du magasin), correction d&#39;un mouvement manuel par mouvement inverse. CMP et seuils faits aux lots 3.6 / 3.9.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-01, RG-STOCK-05</td><td>1.x, R4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-stock-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r4-stock">📷</a></td></tr></tbody></table><h2 id="mouvements-manuels" tabindex="-1">Mouvements manuels <a class="header-anchor" href="#mouvements-manuels" aria-label="Permalink to &quot;Mouvements manuels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Ajustement, perte et vol sous PIN</strong><br><span class="muted">Le caissier ou le gérant déclare une casse, une perte, un vol ou un ajustement en delta, motivé et validé par un PIN manager.<br><i>Caisses : « Casse / perte » sous PIN manager (jeton STOCK_LOSS à usage unique, hors ligne). Back-office : « Déclarer un mouvement » (perte, vol, ajustement ±) sous PIN. Motif obligatoire, sortie seulement pour perte et vol, quantité cible refusée (SET_QUANTITY_FORBIDDEN), motif et validateur portés par le mouvement, audit.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-05, RG-STOCK-06</td><td>3.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-inventaires">📷</a></td></tr><tr><td><strong>Correction par mouvement inverse</strong><br><span class="muted">Un mouvement erroné se corrige par un mouvement inverse motivé et signé qui référence l&#39;original.<br><i>Lot R4 : « Corriger » dans le journal — même type, quantité opposée, motif obligatoire, PIN du manager connecté, audit ; seuls les mouvements manuels et le stock initial, une seule fois, jamais un inverse (409 / 422) ; diffusé aux caisses comme tout mouvement.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-02</td><td>R4</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r4-stock">📷</a></td></tr><tr><td><strong>Stock initial</strong><br><span class="muted">Le stock de départ d&#39;un produit est posé une seule fois, à l&#39;import ou à la création.<br><i>Lot R4 : page « Valeur du stock » — saisie ou import CSV « code-barres ou nom ; quantité » avec aperçu (produit introuvable, non suivi, quantité invalide), une fois par produit (refus détaillé ensuite ; ressaisissable après correction par mouvement inverse), sans PIN (import initial, RG-STOCK-06).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-21</td><td>R4</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r4-stock">📷</a></td></tr><tr><td><strong>Stock négatif configurable</strong><br><span class="muted">Le magasin choisit d&#39;autoriser ou non la vente au-delà du stock, avec dérogation sous PIN manager. Les additions de restaurant aussi : leur premier encaissement, qui sort toute l&#39;addition du stock, est bloqué puis dérogé de la même façon ; les parts suivantes passent.<br><i>Réglé par l&#39;OWNER dans la politique de vente ; à « non », la caisse bloque la vente au comptoir au-delà du stock projeté local (hors ligne compris), dérogeable par PIN manager + motif (jeton NEGATIVE_STOCK à usage unique, porté par la vente et compté par caissier). Additions de restaurant : non bloquées.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-18</td><td>3.9</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-reliquats">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-preuves-push">📷</a></td></tr></tbody></table><h2 id="inventaires" tabindex="-1">Inventaires <a class="header-anchor" href="#inventaires" aria-label="Permalink to &quot;Inventaires&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Inventaire complet ou partiel</strong><br><span class="muted">Le gérant lance un inventaire de tout le magasin ou d&#39;une partie, sans fermer la vente.<br><i>Lancé au back-office (complet ou par catégories), diffusé aux caisses avec rattrapage ; abandon motivé sans mouvement. Zones et gel des ventes pendant un inventaire complet : à faire.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-09</td><td>3.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-inventaires">📷</a></td></tr><tr><td><strong>Comptage mobile par scan</strong><br><span class="muted">Les compteurs scannent les produits à la caméra sur téléphone et saisissent les quantités, hors ligne compris.<br><i>Lot R4 : scan caméra ajouté au comptage (Android : CameraX + ML Kit ; iOS : VisionKit, saisie manuelle en repli) — même chemin que la douchette ; le serveur recalcule le théorique à counted_at.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-STOCK-09</td><td>3.8, R4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-inventaires">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r4-stock">📷</a></td></tr><tr><td><strong>Plusieurs compteurs et conflits</strong><br><span class="muted">Plusieurs personnes comptent en parallèle ; un produit compté deux fois est marqué en conflit avant validation.<br><i>Comptages par compteur (utilisateur ou appareil), progression par compteur ; deux comptages divergents = conflit à trancher explicitement ; comptages arrivés après la clôture rejetés et signalés.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-10</td><td>3.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-inventaires">📷</a></td></tr><tr><td><strong>Validation et ajustements automatiques</strong><br><span class="muted">Le gérant revoit les écarts valorisés puis valide sous PIN, ce qui génère un ajustement par ligne en écart.<br><i>Validation sous PIN, refusée tant qu&#39;un conflit reste ouvert ; un ADJUSTMENT_INVENTORY delta par ligne en écart (motif INVENTORY, inventoryId), projeté et diffusé aux caisses ; écarts valorisés au CMP ; audit.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-11</td><td>3.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-inventaires">📷</a></td></tr></tbody></table><h2 id="lots-peremption" tabindex="-1">Lots &amp; péremption <a class="header-anchor" href="#lots-peremption" aria-label="Permalink to &quot;Lots &amp; péremption&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Lots, DLC et sortie FEFO</strong><br><span class="muted">Les produits suivis en lots portent un numéro et une DLC, et la sortie propose d&#39;abord le lot le plus proche de sa date.<br><i>Lot 4.3 : lot et DLC obligatoires à la réception d&#39;un produit suivi en péremption (422 LOT_REQUIRED), table stock_lots, consommation FEFO par les ventes projetées (lot choisi par le serveur), page « Péremption » (lots par DLC, périmés / bientôt, sortie en perte LOSS motif EXPIRY). Restes : choix manuel du lot en caisse tracé, retours réalimentant un lot.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-12</td><td>4.3</td><td><a href="/VendoraSystem-docs/preuves/2026-11-06-43-profils-magasin">📷</a></td></tr><tr><td><strong>Alertes de péremption</strong><br><span class="muted">Le gérant voit les lots bientôt périmés ou périmés et les sort en perte motivée.<br><i>Lot 4.3 : seuil par produit (expiry_alert_days) ; alerte « bientôt périmé » puis « périmé » une fois par lot et par palier, poussée aux responsables (back-office, caisses, notification) par le planificateur horaire et à chaque lecture des lots.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-13</td><td>4.3</td><td><a href="/VendoraSystem-docs/preuves/2026-11-06-43-profils-magasin">📷</a></td></tr></tbody></table><h2 id="alertes-valorisation" tabindex="-1">Alertes &amp; valorisation <a class="header-anchor" href="#alertes-valorisation" aria-label="Permalink to &quot;Alertes &amp; valorisation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Alerte de seuil bas</strong><br><span class="muted">Le gérant est notifié une fois quand un produit passe sous son seuil, avec un lien vers une suggestion de commande. Le passage sous le seuil est aussi diffusé aux appareils : notification aux responsables connectés et écran « Alertes ».<br><i>Seuil par produit (lot 3.6) ; alertes stock filtrables et carte au tableau de bord ; email aux responsables une seule fois par franchissement, réarmé quand le stock repasse au-dessus, avec le lien vers la suggestion de commande. Push mobile : avec l&#39;application de consultation.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-14</td><td>3.6, 3.9</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-reliquats">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-preuves-push">📷</a></td></tr><tr><td><strong>Valorisation au coût moyen pondéré</strong><br><span class="muted">Le propriétaire voit la valeur de son stock au CMP, recalculé à chaque réception.<br><i>Lot R4 : valeur du stock au CMP par produit et totale (produits en stock sans coût connu signalés à part), export CSV ; CMP recalculé à chaque réception (lot 3.6). 10/11 : CMP daté (historique, V95) : les ventes sont valorisées au CMP de leur heure, rattrapage compris. Reste : pertes / écarts d&#39;inventaire au CMP de leur date.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-15</td><td>3.6, R4, cartes-09/11</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r4-stock">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-09-rapports-logo-cmp-ecritures">📷</a></td></tr></tbody></table><h2 id="variantes-recettes-transferts" tabindex="-1">Variantes, recettes &amp; transferts <a class="header-anchor" href="#variantes-recettes-transferts" aria-label="Permalink to &quot;Variantes, recettes &amp; transferts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Stock par variante</strong><br><span class="muted">Pour un produit à variantes, le stock est suivi par variante et le stock produit en est la somme.<br><i>Phase 3, module variants (profil APPAREL).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-STOCK-16</td><td></td><td></td></tr><tr><td><strong>Décomposition des plats en ingrédients</strong><br><span class="muted">La vente d&#39;un plat avec fiche technique sort chaque ingrédient du stock, valorisé au CMP, selon la version de fiche en vigueur.<br><i>Livré au lot 3.14 : la caisse sort les ingrédients du plat (hors ligne, version figée), annulation qui les rend, retour sans remise en stock, stock insuffisant contrôlé sur les ingrédients, rattrapage des caisses mises à jour.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-22, RG-STOCK-23, RG-STOCK-24</td><td>3.14</td><td><a href="/VendoraSystem-docs/preuves/2026-11-02-314-food-cost">📷</a></td></tr><tr><td><strong>Transferts entre magasins</strong><br><span class="muted">Un transfert crée une paire de mouvements sortie / entrée entre deux magasins du même tenant.<br><i>Phase 3, multi-magasins (spec 14).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-STOCK-08</td><td></td><td></td></tr></tbody></table><h2 id="anti-fraude" tabindex="-1">Anti-fraude <a class="header-anchor" href="#anti-fraude" aria-label="Permalink to &quot;Anti-fraude&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Agrégats anti-fraude du stock</strong><br><span class="muted">Le propriétaire dispose, par caissier et par appareil, de la somme et de la fréquence des écarts, pertes et retours sans ticket.<br><i>Par caissier : écarts d&#39;inventaire retenus (nombre, valeur au CMP), pertes et vols déclarés, retours sans ticket, ventes dérogées au stock, à côté des remises, annulations, tiroir et écarts de caisse.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-STOCK-19</td><td>3.9</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-reliquats">📷</a></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Correction par mouvement inverse (reversalOfMovementId) et stock initial au back-office.</li><li>Inventaires : scan caméra, zones, gel des ventes pendant un inventaire complet.</li><li>Valeur totale du stock, filtres et export CSV de l&#39;écran Stock.</li><li>Stock par variante, décomposition des plats en ingrédients, transferts entre magasins.</li><li>Péremption : choix manuel du lot en caisse (tracé), retours réalimentant un lot, seuil d&#39;alerte par magasin en plus du seuil par produit.</li></ul>',24)])])}const m=a(d,[["render",r]]);export{h as __pageData,m as default};
